// Продолжение: задачи 401–600. Исходный catalog.mjs не изменяется.
export const extra=[];
let topic='';
function section(name){topic=name;}
function q(title,body,answer,why,decl='',imports='fmt'){
 extra.push({id:401+extra.length,topic,title,source:`package main\n${imports?'import ('+imports.split(',').map(s=>'"'+s+'"').join(';')+')\n':''}${decl}\nfunc main(){${body}}\n`,kind:'run',answer:answer.trimEnd(),why});
}
function bad(title,body,diagnostic,why,decl='',imports='fmt'){q(title,body,diagnostic,why,decl,imports);extra.at(-1).kind='compile';}
section('Функциональные адаптеры: поведение из функции');
q('Функция становится обработчиком','h:=HandlerFunc(func(n int)int{return n*2});fmt.Println(use(h,3))','6','Определённый функциональный тип с методом адаптирует callback к интерфейсу.','type Handler interface{Handle(int)int};type HandlerFunc func(int)int;func(f HandlerFunc)Handle(n int)int{return f(n)};func use(h Handler,n int)int{return h.Handle(n)}');
bad('Литерал функции вместо адаптера','use(func(n int)int{return n})','does not implement','Совпадение сигнатуры функции с сигнатурой метода не означает реализацию интерфейса.','type Handler interface{Handle(int)int};func use(Handler){}','');
q('Адаптер не вызывает callback при создании','n:=0;h:=F(func(){n++});fmt.Print(n," ");h.Run();fmt.Println(n)','0 1','Конверсия функции в определённый функциональный тип не исполняет её тело.','type F func();func(f F)Run(){f()}');
q('Nil-функция с обработкой в адаптере','var f F;var r interface{Run()string}=f;fmt.Println(r==nil,r.Run())','false skipped','Адаптер может явно задать поведение nil-callback; интерфейс при этом не nil.','type F func()string;func(f F)Run()string{if f==nil{return "skipped"};return f()}');
q('Обёртка не делает копию захваченного состояния','n:=1;f:=F(func()int{return n});var r interface{Read()int}=f;n=9;fmt.Println(r.Read())','9','Интерфейс копирует функциональное значение, но замыкание сохраняет связь с переменной n.','type F func()int;func(f F)Read()int{return f()}');
q('Замена функции после упаковки','f:=F(func()int{return 1});var r interface{Read()int}=f;f=func()int{return 2};fmt.Println(r.Read(),f.Read())','1 2','Интерфейс хранит прежнее функциональное значение, а не адрес переменной f.','type F func()int;func(f F)Read()int{return f()}');
q('Указательный адаптер видит замену callback','f:=F(func()int{return 1});var r interface{Read()int}=&f;f=func()int{return 2};fmt.Println(r.Read())','2','Указательный получатель позволяет интерфейсу читать текущее значение переменной функции.','type F func()int;func(f *F)Read()int{return (*f)()}');
bad('Метод адаптера с другим результатом','var r interface{Read()any}=F(func()int{return 1});_ = r','does not implement','Функциональному адаптеру не предоставляется ковариантность результата метода.','type F func()int;func(f F)Read()int{return f()}','');
q('Адаптер явно упаковывает результат','var r interface{Read()any}=F(func()int{return 3});fmt.Printf("%T %v\\n",r.Read(),r.Read())','int 3','Метод адаптера может иметь интерфейсный результат, явно задавая границу упаковки.','type F func()int;func(f F)Read()any{return f()}');
q('Функция-адаптер и два независимых интерфейса','f:=F(func(n int)int{return n+1});var a interface{Apply(int)int}=f;var b interface{Twice(int)int}=f;fmt.Println(a.Apply(2),b.Twice(2))','3 4','Один функциональный тип может реализовать несколько интерфейсов разными методами.','type F func(int)int;func(f F)Apply(n int)int{return f(n)};func(f F)Twice(n int)int{return f(f(n))}');
q('Декоратор функционального адаптера','var log []string;h:=decorate(F(func(){log=append(log,"body")}),&log);h.Run();fmt.Println(log)','[before body after]','Декоратор возвращает новый адаптер, сохраняя внутренний вызов и заданный порядок эффектов.','type F func();func(f F)Run(){f()};func decorate(next interface{Run()},log *[]string)F{return func(){*log=append(*log,"before");next.Run();*log=append(*log,"after")}}');
q('Адаптер ReaderFunc сохраняет n вместе с EOF','r:=RF(func(p []byte)(int,error){p[0]=\'x\';return 1,io.EOF});b,err:=io.ReadAll(r);fmt.Printf("%s %v\\n",b,err)','x <nil>','ReadAll обрабатывает полученные байты и считает EOF нормальным завершением.','type RF func([]byte)(int,error);func(f RF)Read(p []byte)(int,error){return f(p)}','fmt,io');
q('WriterFunc с короткой записью','w:=WF(func(p []byte)(int,error){return len(p)-1,nil});n,err:=io.Copy(w,strings.NewReader("abc"));fmt.Println(n,errors.Is(err,io.ErrShortWrite))','2 true','Адаптация сигнатуры не снимает договор Writer: короткая запись без ошибки превращается в ErrShortWrite.','type WF func([]byte)(int,error);func(f WF)Write(p []byte)(int,error){return f(p)}','fmt,io,strings,errors');
q('http.HandlerFunc меняет тип функции','h:=http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){fmt.Fprint(w,r.Method)});rec:=httptest.NewRecorder();h.ServeHTTP(rec,httptest.NewRequest("PATCH","/",nil));fmt.Println(rec.Code,rec.Body.String())','200 PATCH','HandlerFunc добавляет метод ServeHTTP обычной функции; сеть для вызова адаптера не нужна.','','fmt,net/http,net/http/httptest');
bad('http.Handler требует метод','var h http.Handler=func(http.ResponseWriter,*http.Request){};_ = h','does not implement','Функцию нужно явно адаптировать типом http.HandlerFunc.','','net/http');
q('Функциональный адаптер как ключ интерфейсной карты','defer func(){fmt.Println(recover()!=nil)}();var r interface{Run()}=F(func(){});m:=map[any]int{};m[r]=1','true','Наличие методов не делает underlying-функцию сравнимой и хешируемой.','type F func();func(f F)Run(){f()}');
q('Адаптер со значением receiver возвращает новый тип','f:=F(func(n int)int{return n*2});g:=f.Then(func(n int)int{return n+1});fmt.Printf("%T %v\\n",g,g(3))','main.F 7','Метод определённого функционального типа может возвращать следующий адаптер того же типа.','type F func(int)int;func(f F)Then(g func(int)int)F{return func(n int)int{return g(f(n))}}');
q('Конверсия двух адаптеров разделяет closure','n:=0;a:=A(func()int{n++;return n});b:=B(a);fmt.Println(a.Get(),b.Load())','1 2','Разные имена и методы не разделяют состояние функции при допустимой конверсии типов.','type A func()int;type B func()int;func(f A)Get()int{return f()};func(f B)Load()int{return f()}');
bad('Адаптер с variadic-методом','var r interface{Apply([]int)int}=F(func(x ...int)int{return len(x)});_ = r','does not implement','Apply(...int) и Apply([]int) — разные сигнатуры метода.','type F func(...int)int;func(f F)Apply(x ...int)int{return f(x...)}','');
q('Явный мост между variadic и срезом','f:=F(func(x ...int)int{return len(x)});var r interface{Apply([]int)int}=f;fmt.Println(r.Apply([]int{1,2,3}))','3','Метод принимает обычный срез и сам выбирает форму раскрытия аргументов внутренней функции.','type F func(...int)int;func(f F)Apply(x []int)int{return f(x...)}');
section('Адаптеры коллекций и алгоритмы через операции');
q('Sort переставляет исходный срез','s:=[]int{3,1,2};sort.Sort(Ints(s));fmt.Println(s)','[1 2 3]','Срезовый адаптер меняет общий массив через Swap, несмотря на value receiver.','type Ints []int;func(s Ints)Len()int{return len(s)};func(s Ints)Less(i,j int)bool{return s[i]<s[j]};func(s Ints)Swap(i,j int){s[i],s[j]=s[j],s[i]}','fmt,sort');
q('Массивный адаптер со Swap на копии','a:=A{2,1};a.Swap(0,1);fmt.Println(a)','[2 1]','Метод с value receiver массива переставляет элементы собственной копии.','type A [2]int;func(a A)Swap(i,j int){a[i],a[j]=a[j],a[i]}');
q('Массивный адаптер с указательным Swap','a:=A{2,1};sort.Sort(&a);fmt.Println(a)','[1 2]','Для изменения массива адаптер передаётся указателем и реализует Swap на *A.','type A [2]int;func(a A)Len()int{return len(a)};func(a A)Less(i,j int)bool{return a[i]<a[j]};func(a *A)Swap(i,j int){a[i],a[j]=a[j],a[i]}','fmt,sort');
bad('Передача значения при pointer Swap','a:=A{2,1};sort.Sort(a)','does not implement','Множество методов A не включает Swap с указательным получателем.','type A [2]int;func(a A)Len()int{return 2};func(a A)Less(i,j int)bool{return a[i]<a[j]};func(a *A)Swap(i,j int){a[i],a[j]=a[j],a[i]}','sort');
q('Reverse декорирует сравнение','s:=sort.IntSlice{2,1,3};sort.Sort(sort.Reverse(s));fmt.Println(s)','[3 2 1]','Reverse меняет порядок сравнения, сохраняя Len и Swap исходного адаптера.','','fmt,sort');
q('Двойной Reverse','s:=sort.IntSlice{3,1,2};sort.Sort(sort.Reverse(sort.Reverse(s)));fmt.Println(s)','[1 2 3]','Две инверсии Less восстанавливают исходное направление порядка.','','fmt,sort');
q('Стабильная сортировка через адаптер','s:=Rows{{1,"a"},{0,"x"},{1,"b"}};sort.Stable(s);fmt.Println(s)','[{0 x} {1 a} {1 b}]','Stable сохраняет взаимный порядок элементов, которые Less считает эквивалентными.','type Row struct{K int;Name string};type Rows []Row;func(s Rows)Len()int{return len(s)};func(s Rows)Less(i,j int)bool{return s[i].K<s[j].K};func(s Rows)Swap(i,j int){s[i],s[j]=s[j],s[i]}','fmt,sort');
q('Индексный поиск не видит тип элемента','s:=[]string{"a","go","x"};job:=Query{len(s),func(i int)bool{return len(s[i])==2}};fmt.Println(find(job))','1','Индексный контракт оставляет доступ к типизированным данным внутри callback.','type Query struct{N int;Match func(int)bool};func find(q Query)int{for i:=0;i<q.N;i++{if q.Match(i){return i}};return -1}');
q('Предикат меняет следующий элемент','s:=[]int{1,2,3};q:=Query{len(s),func(i int)bool{if i==0{s[1]=9};return s[i]==9}};fmt.Println(find(q),s)','1 [1 9 3]','Алгоритм вызывает callback по ходу обхода; адаптер не создаёт снимок элементов.','type Query struct{N int;Match func(int)bool};func find(q Query)int{for i:=0;i<q.N;i++{if q.Match(i){return i}};return -1}');
q('Зафиксированная длина и растущий источник','s:=[]int{1};q:=Query{len(s),func(i int)bool{s=append(s,9);return s[i]==9}};fmt.Println(find(q),len(s))','-1 2','Сохранённая в адаптере длина не увеличивается вслед за переменной среза.','type Query struct{N int;Match func(int)bool};func find(q Query)int{for i:=0;i<q.N;i++{if q.Match(i){return i}};return -1}');
q('Адаптер накопления с value receiver','f:=Fold{Values:[]int{1,2}};run(f);fmt.Println(f.Total)','0','Каждый Add работает с копией Fold; интерфейсный вызов не превращает value receiver в указатель.','type Fold struct{Values []int;Total int};func(f Fold)Len()int{return len(f.Values)};func(f Fold)Add(i int){f.Total+=f.Values[i]};func run(f interface{Len()int;Add(int)}){for i:=0;i<f.Len();i++{f.Add(i)}}');
q('Адаптер накопления с pointer receiver','f:=Fold{Values:[]int{1,2}};run(&f);fmt.Println(f.Total)','3','Указательный адаптер хранит общий типизированный аккумулятор вне общего цикла.','type Fold struct{Values []int;Total int};func(f *Fold)Len()int{return len(f.Values)};func(f *Fold)Add(i int){f.Total+=f.Values[i]};func run(f interface{Len()int;Add(int)}){for i:=0;i<f.Len();i++{f.Add(i)}}');
q('Map-адаптер пишет префикс до ошибки','out:=make([]int,3);err:=run(Job{[]int{1,-1,3},out});fmt.Println(out,err!=nil)','[2 0 0] true','Общий цикл прекращается на ошибке, но уже записанные элементы не откатываются.','type Job struct{In,Out []int};func(j Job)Len()int{return len(j.In)};func(j Job)Apply(i int)error{if j.In[i]<0{return fmt.Errorf("negative")};j.Out[i]=2*j.In[i];return nil};func run(j interface{Len()int;Apply(int)error})error{for i:=0;i<j.Len();i++{if e:=j.Apply(i);e!=nil{return e}};return nil}');
q('Общий In и Out влияет на последующие чтения','s:=[]int{1,2,3};j:=Job{s[:2],s[1:]};for i:=0;i<2;i++{j.Apply(i)};fmt.Println(s)','[1 10 100]','Выход сдвинут внутри того же массива; первая запись меняет следующий вход.','type Job struct{In,Out []int};func(j Job)Apply(i int){j.Out[i]=j.In[i]*10}');
q('Копия адаптера всё ещё разделяет срез','a:=Job{[]int{1,2}};b:=a;b.Values[0]=9;fmt.Println(a.Values)','[9 2]','Копирование структуры адаптера копирует только заголовок его среза.','type Job struct{Values []int}');
q('Адаптер хранит старый заголовок','s:=make([]int,1,3);a:=View{s};s=append(s,9);fmt.Println(a.Len(),a.Values[:2])','1 [0 9]','Длина сохранённого заголовка старая, но доступный массив общий.','type View struct{Values []int};func(v View)Len()int{return len(v.Values)}');
q('Адаптер хранит указатель на заголовок','s:=[]int{1};a:=View{&s};s=append(s,2);fmt.Println(a.Len())','2','Указатель на переменную среза позволяет адаптеру видеть замену её заголовка.','type View struct{Values *[]int};func(v View)Len()int{return len(*v.Values)}');
q('Два вида представления одной коллекции','s:=[]int{4,2,8};fmt.Println(MinView(s).Pick(),MaxView(s).Pick())','2 8','Разные определённые типы адаптируют одни данные к разному поведению без копирования элементов.','type MinView []int;func(s MinView)Pick()int{return slices.Min(s)};type MaxView []int;func(s MaxView)Pick()int{return slices.Max(s)}','fmt,slices');
bad('Адаптер коллекции не адаптер элемента','var x interface{Less(int,int)bool}=Item(3);_ = x','does not implement','Метод сравнения элемента с элементом не совпадает с индексной сигнатурой коллекционного контракта.','type Item int;func(i Item)Less(j Item)bool{return i<j}','');
q('Слой адаптера выбирает первый результат','s:=[]int{2,1,1};fmt.Println(pick(View{s}))','1','Строгое сравнение при обновлении сохраняет первый индекс минимального элемента.','type View struct{S []int};func(v View)Len()int{return len(v.S)};func(v View)Less(i,j int)bool{return v.S[i]<v.S[j]};func pick(v interface{Len()int;Less(int,int)bool})int{best:=0;for i:=1;i<v.Len();i++{if v.Less(i,best){best=i}};return best}');
section('Callback: ошибки, состояние и порядок эффектов');
q('All останавливается до опасного callback','calls:=0;ok:=all([]int{0,1},func(n int)bool{calls++;if n==1{panic("late")};return n>0});fmt.Println(ok,calls)','false 1','Короткое замыкание определяет не только результат, но и набор выполненных эффектов.','func all(s []int,p func(int)bool)bool{for _,v:=range s{if !p(v){return false}};return true}');
q('Пустой вход с nil-предикатом','fmt.Println(all(nil,nil))','true','Данный цикл не вызывает callback для пустого входа; nil сам по себе не паникует.','func all(s []int,p func(int)bool)bool{for _,v:=range s{if !p(v){return false}};return true}');
q('Проверка callback меняет договор пустого входа','defer func(){fmt.Println(recover()!=nil)}();fmt.Println(all(nil,nil))','true','Явная проверка предусловия выполняется до обхода и отвергает nil даже для пустого входа.','func all(s []int,p func(int)bool)bool{if p==nil{panic("nil predicate")};for _,v:=range s{if !p(v){return false}};return true}');
q('Ошибка callback не отменяет побочный эффект','events:=[]int{};sum,err:=fold([]int{1,2,3},func(a,v int)(int,error){events=append(events,v);if v==2{return 99,fmt.Errorf("stop")};return a+v,nil});fmt.Println(sum,err!=nil,events)','1 true [1 2]','Fold сохраняет последний успешный аккумулятор, но журнал ошибочного callback уже изменён.','func fold(s []int,f func(int,int)(int,error))(int,error){a:=0;for _,v:=range s{n,e:=f(a,v);if e!=nil{return a,e};a=n};return a,nil}');
q('Фиксация результата перед проверкой error','n,err:=fold([]int{1,2},func(a,v int)(int,error){if v==2{return 99,fmt.Errorf("stop")};return a+v,nil});fmt.Println(n,err!=nil)','99 true','Порядок присваивания аккумулятора и проверки ошибки является частью договора алгоритма.','func fold(s []int,f func(int,int)(int,error))(a int,e error){for _,v:=range s{a,e=f(a,v);if e!=nil{return}};return}');
q('Typed nil error останавливает обработку','calls:=0;err:=each([]int{1,2},func(int)error{calls++;var e *E;return e});fmt.Println(err==nil,calls)','false 1','Callback упаковывает nil-указатель в error; проверка err != nil считает его ошибкой.','type E struct{};func(*E)Error()string{return "E"};func each(s []int,f func(int)error)error{for _,v:=range s{if e:=f(v);e!=nil{return e}};return nil}');
q('Обёртка нормализует typed nil error','f:=func()*E{return nil};cb:=func()error{if e:=f();e!=nil{return e};return nil};fmt.Println(cb()==nil)','true','Адаптер явно возвращает nil-интерфейс, когда конкретный указатель ошибки равен nil.','type E struct{};func(*E)Error()string{return "E"}');
q('Callback получает структуру-копию','s:=[]Item{{1}};visit(s,func(v Item){v.N=9});fmt.Println(s[0].N)','1','Callback с параметром Item изменяет копию элемента.','type Item struct{N int};func visit(s []Item,f func(Item)){for _,v:=range s{f(v)}}');
q('Callback получает адрес элемента','s:=[]Item{{1}};visit(s,func(v *Item){v.N=9});fmt.Println(s[0].N)','9','Передача &s[i] даёт callback доступ к исходному элементу.','type Item struct{N int};func visit(s []Item,f func(*Item)){for i:=range s{f(&s[i])}}');
q('Адрес копии range не адрес элемента','s:=[]Item{{1}};visit(s,func(v *Item){v.N=9});fmt.Println(s[0].N)','1','&v указывает на переменную итерации, а не на s[i].','type Item struct{N int};func visit(s []Item,f func(*Item)){for _,v:=range s{f(&v)}}');
q('Сохраняемые callbacks читают один аккумулятор','n:=0;var fs []func()int;for _,v:=range []int{1,2}{n+=v;fs=append(fs,func()int{return n})};fmt.Println(fs[0](),fs[1]())','3 3','Новые переменные range не делают внешнюю переменную n отдельной для каждой итерации.');
q('Callback сохраняет снимок суммы','n:=0;var fs []func()int;for _,v:=range []int{1,2}{n+=v;snapshot:=n;fs=append(fs,func()int{return snapshot})};fmt.Println(fs[0](),fs[1]())','1 3','Переменная внутри тела цикла создаёт отдельный снимок состояния для каждого замыкания.');
q('Замена callback во время обхода','calls:=[]int{};var f func(int);f=func(n int){calls=append(calls,n);f=func(n int){calls=append(calls,n*10)}};each([]int{1,2},f);fmt.Println(calls)','[1 2]','Параметр each содержит переданное функциональное значение; замена внешней переменной f его не меняет.','func each(s []int,f func(int)){for _,v:=range s{f(v)}}');
q('Указатель на callback меняет следующий вызов','calls:=[]int{};var f func(int);f=func(n int){calls=append(calls,n);f=func(n int){calls=append(calls,n*10)}};each([]int{1,2},&f);fmt.Println(calls)','[1 20]','Каждая итерация разыменовывает переменную функции заново.','func each(s []int,f *func(int)){for _,v:=range s{(*f)(v)}}');
q('Предикат с состоянием не математический фильтр','n:=0;p:=func(int)bool{n++;return n%2==1};fmt.Println(filter([]int{1,2,3},p),filter([]int{1,2,3},p))','[1 3] [2]','Повторное использование stateful-предиката делает результат зависимым от предыдущих вызовов.','func filter(s []int,p func(int)bool)(out []int){for _,v:=range s{if p(v){out=append(out,v)}};return}');
q('Map изменяет данные до следующего чтения','s:=[]int{1,2};out:=mapInts(s,func(n int)int{s[1]=9;return n*2});fmt.Println(out,s)','[2 18] [1 9]','Новый массив результата не означает снимок входа; callback меняет ещё не прочитанный элемент.','func mapInts(s []int,f func(int)int)[]int{out:=make([]int,len(s));for i,v:=range s{out[i]=f(v)};return out}');
q('Сохранённые указатели на один объект','box:=Item{};out:=mapPtrs([]int{1,2},func(n int)*Item{box.N=n;return &box});fmt.Println(out[0]==out[1],out[0].N)','true 2','Тип результата *Item не обещает, что callback создаёт независимый объект для каждого элемента.','type Item struct{N int};func mapPtrs(s []int,f func(int)*Item)(out []*Item){for _,v:=range s{out=append(out,f(v))};return}');
q('Функция возвращает nil-срез как успешный результат','r,e:=apply(func()([]int,error){return nil,nil});fmt.Println(r==nil,e==nil)','true true','Нулевой результат и отсутствие ошибки — независимые части договора callback.','func apply(f func()([]int,error))([]int,error){return f()}');
bad('Callback с конкретной ошибкой','run(func()*E{return nil})','cannot use','func()*E не присваивается func()error; нужен явный адаптер результата.','type E struct{};func(*E)Error()string{return "E"};func run(func()error){}','');
q('Callback получает значение до побочного эффекта','n:=1;f:=func(v int){fmt.Println(v,n)};arg:=func()int{old:=n;n=9;return old};f(arg())','1 9','Аргумент вычисляется до входа в callback; переданное значение и текущее внешнее состояние различаются.');
section('Функции высшего порядка: композиция и частичное применение');
q('Порядок композиции имеет значение','inc:=func(n int)int{return n+1};dbl:=func(n int)int{return n*2};fmt.Println(compose(inc,dbl)(3),compose(dbl,inc)(3))','7 8','compose(f,g) означает f(g(x)); перестановка функций меняет результат.','func compose(f,g func(int)int)func(int)int{return func(x int)int{return f(g(x))}}');
q('Создание композиции не запускает слои','n:=0;f:=func(x int)int{n++;return x};c:=compose(f,f);fmt.Print(n," ");fmt.Println(c(1),n)','0 1 2','Возвращаемое замыкание откладывает оба вызова до получения аргумента.','func compose(f,g func(int)int)func(int)int{return func(x int)int{return f(g(x))}}');
q('Bind фиксирует скалярный аргумент','n:=2;f:=bind(func(a,b int)int{return a+b},n);n=9;fmt.Println(f(3))','5','Параметр bind хранит копию значения, переданного при частичном применении.','func bind(f func(int,int)int,a int)func(int)int{return func(b int)int{return f(a,b)}}');
q('Bind фиксирует указатель','n:=2;f:=bind(func(a *int,b int)int{return *a+b},&n);n=9;fmt.Println(f(3))','12','Фиксация указателя не делает снимок объекта, на который он указывает.','func bind(f func(*int,int)int,a *int)func(int)int{return func(b int)int{return f(a,b)}}');
q('Каррирование создаёт независимые окружения','add2:=curry(2);add5:=curry(5);fmt.Println(add2(3),add5(3))','5 8','Каждый вызов внешней функции создаёт свою переменную захваченного параметра.','func curry(a int)func(int)int{return func(b int)int{return a+b}}');
q('Копия счётчика-функции разделяет состояние','a:=counter();b:=a;fmt.Println(a(),b(),a())','1 2 3','Копирование замыкания сохраняет одно захваченное состояние.','func counter()func()int{n:=0;return func()int{n++;return n}}');
q('Два вызова фабрики не делят состояние','a,b:=counter(),counter();fmt.Println(a(),b(),a())','1 1 2','Отдельные вызовы фабрики создают отдельные переменные n.','func counter()func()int{n:=0;return func()int{n++;return n}}');
q('Memo кеширует нулевой результат','calls:=0;f:=memo(func(int)int{calls++;return 0});fmt.Println(f(1),f(1),calls)','0 0 1','Наличие ключа нужно проверять через comma-ok, а не через ненулевой результат.','func memo(f func(int)int)func(int)int{cache:=map[int]int{};return func(n int)int{if v,ok:=cache[n];ok{return v};v:=f(n);cache[n]=v;return v}}');
q('Memo с проверкой по нулю вызывает повторно','calls:=0;f:=memo(func(int)int{calls++;return 0});f(1);f(1);fmt.Println(calls)','2','Нулевое значение успешного результата ошибочно принято за отсутствие записи.','func memo(f func(int)int)func(int)int{cache:=map[int]int{};return func(n int)int{if cache[n]!=0{return cache[n]};cache[n]=f(n);return cache[n]}}');
q('Композиция Map меняет журнал','var log []string;f:=func(n int)int{log=append(log,"f");return n+1};g:=func(n int)int{log=append(log,"g");return n*2};_ = mapInts(mapInts([]int{1,2},f),g);fmt.Println(log);log=nil;_ = mapInts([]int{1,2},func(n int)int{return g(f(n))});fmt.Println(log)','[f f g g]\n[f g f g]','Равенство конечных чисел не гарантирует равенство наблюдаемых эффектов двух и одного проходов.','func mapInts(s []int,f func(int)int)(out []int){for _,v:=range s{out=append(out,f(v))};return}');
q('Композиция с ошибкой не вызывает второй слой','calls:=0;f:=func(int)(int,error){return 0,fmt.Errorf("stop")};g:=func(n int)(int,error){calls++;return n,nil};_,e:=then(f,g)(1);fmt.Println(e!=nil,calls)','true 0','Error-aware композиция должна явно определить короткое замыкание между слоями.','func then(f,g func(int)(int,error))func(int)(int,error){return func(n int)(int,error){v,e:=f(n);if e!=nil{return v,e};return g(v)}}');
q('Один defer охватывает всю композицию','var log []string;f:=around(func(){log=append(log,"body")},&log);f();fmt.Println(log)','[enter body leave]','Внешнее замыкание задаёт область действия defer вокруг вызова следующего слоя.','func around(next func(),log *[]string)func(){return func(){*log=append(*log,"enter");defer func(){*log=append(*log,"leave")}();next()}}');
q('recover в фабрике не защищает будущий вызов','defer func(){fmt.Println("outer",recover()!=nil)}();f:=factory();f()','outer true','Defer фабрики уже завершился к моменту вызова возвращённой функции.','func factory()func(){defer func(){_ = recover()}();return func(){panic("later")}}');
q('recover внутри возвращённой функции','f:=protect(func(){panic("bad")});fmt.Println(f())','true','Перехват должен находиться в стеке фактического вызова опасного callback.','func protect(next func())func()(failed bool){return func()(failed bool){defer func(){failed=recover()!=nil}();next();return false}}');
q('Middleware строится снаружи внутрь','var log []string;f:=wrap("A",wrap("B",func(){log=append(log,"X")},&log),&log);f();fmt.Println(log)','[A+ B+ X B- A-]','Вход проходит по вложенным обёрткам вперёд, а выход разворачивается в обратном порядке.','func wrap(name string,next func(),log *[]string)func(){return func(){*log=append(*log,name+"+");next();*log=append(*log,name+"-")}}');
q('Ленивый fallback вызывается только при отсутствии','n:=0;fallback:=func()int{n++;return 9};fmt.Println(orElse(3,true,fallback),n)','3 0','Передача функции вместо заранее вычисленного значения позволяет избежать ненужного эффекта.','func orElse(v int,ok bool,f func()int)int{if ok{return v};return f()}');
q('Готовое fallback-значение вычисляется заранее','n:=0;fallback:=func()int{n++;return 9};fmt.Println(orElse(3,true,fallback()),n)','3 1','Обычный аргумент вычисляется независимо от того, воспользуется ли им функция.','func orElse(v int,ok bool,fallback int)int{if ok{return v};return fallback}');
q('Функция-фабрика возвращает nil по ветке','defer func(){fmt.Println(recover()!=nil)}();f:=choose(false);f()','true','Корректный функциональный тип результата не гарантирует наличие вызываемого значения.','func choose(ok bool)func(){if ok{return func(){}};return nil}');
bad('Композиция с потерянной связью типов','fmt.Println(compose(func(int)string{return "x"},func(string)int{return 1})(1))','cannot use','Две функции func(any)any нельзя получить автоматической конверсией конкретных сигнатур.','func compose(f,g func(any)any)func(any)any{return func(x any)any{return f(g(x))}}');
q('Generic-композиция сохраняет промежуточный тип','f:=compose(func(n int)string{return fmt.Sprint(n)},func(s string)int{return len(s)});fmt.Printf("%T %v\\n",f,f("go"))','func(string) string 2','Промежуточный B связывает результат g с аргументом f и остаётся проверяемым статически.','func compose[A,B,C any](f func(B)C,g func(A)B)func(A)C{return func(a A)C{return f(g(a))}}');
section('Generic-алгоритмы: связи входа, результата и ошибок');
q('Map меняет тип элемента','out:=Map([]int{2,3},func(n int)string{return fmt.Sprint(n*n)});fmt.Printf("%T %v\\n",out,out)','[]string [4 9]','Два независимых параметра типов связываются через сигнатуру callback.','func Map[E,R any](s []E,f func(E)R)[]R{out:=make([]R,len(s));for i,v:=range s{out[i]=f(v)};return out}');
q('Map сохраняет имя выходного среза','out:=Map[Names]([]int{2,3},func(n int)string{return fmt.Sprint(n)});fmt.Printf("%T %v\\n",out,out)','main.Names [2 3]','Явный параметр выходного контейнера позволяет сохранить определённый тип среза.','type Names []string;func Map[Out ~[]R,E,R any](s []E,f func(E)R)Out{out:=make(Out,len(s));for i,v:=range s{out[i]=f(v)};return out}');
bad('Тип назначения не выбирает Out','var out Names=Map([]int{1},func(n int)string{return fmt.Sprint(n)});fmt.Println(out)','cannot infer','Параметр Out присутствует только в результате и ограничении; назначение вызова его не выводит.','type Names []string;func Map[Out ~[]R,E,R any](s []E,f func(E)R)Out{return nil}');
q('Generic Map с make меняет nilness','var in []int;out:=Map(in,func(n int)string{return fmt.Sprint(n)});fmt.Println(out==nil,len(out))','false 0','Выделение make(...,0) даёт пустой не-nil результат даже для nil-входа.','func Map[E,R any](s []E,f func(E)R)[]R{out:=make([]R,len(s));for i,v:=range s{out[i]=f(v)};return out}');
q('Filter сохраняет определённый тип','out:=Filter(Numbers{1,2,3},func(n int)bool{return n>1});fmt.Printf("%T %v\\n",out,out)','main.Numbers [2 3]','Параметр S сохраняет имя контейнера, а E связывает элементы с предикатом.','type Numbers []int;func Filter[S ~[]E,E any](s S,p func(E)bool)S{out:=make(S,0,len(s));for _,v:=range s{if p(v){out=append(out,v)}};return out}');
q('Filter на месте меняет входной массив','s:=[]int{1,2,3};out:=Filter(s,func(n int)bool{return n>1});fmt.Println(out,s)','[2 3] [2 3 3]','Повторное использование s[:0] экономит выделение, но изменяет данные исходного среза.','func Filter[S ~[]E,E any](s S,p func(E)bool)S{out:=s[:0];for _,v:=range s{if p(v){out=append(out,v)}};return out}');
q('Reduce накапливает другой тип','s:=Reduce([]int{1,2,3},"",func(a string,v int)string{return a+fmt.Sprint(v)});fmt.Printf("%T %v\\n",s,s)','string 123','Тип аккумулятора A не обязан совпадать с типом элемента E.','func Reduce[E,A any](s []E,a A,f func(A,E)A)A{for _,v:=range s{a=f(a,v)};return a}');
q('Неявный тип seed ограничивает Reduce','fmt.Printf("%T\\n",Reduce([]int{1},int64(0),func(a int64,v int)int64{return a+int64(v)}))','int64','Тип начального значения участвует в выводе A вместе с сигнатурой reducer.','func Reduce[E,A any](s []E,a A,f func(A,E)A)A{for _,v:=range s{a=f(a,v)};return a}');
bad('Seed и reducer противоречат друг другу','fmt.Println(Reduce([]int{1},0,func(a int64,v int)int32{return int32(a)+int32(v)}))','does not match','Один A должен одновременно совпасть с типом аргумента и результата reducer.','func Reduce[E,A any](s []E,a A,f func(A,E)A)A{return a}');
q('Generic MapErr возвращает только успешный префикс','out,err:=MapErr([]int{1,-1,3},func(n int)(string,error){if n<0{return "bad",fmt.Errorf("negative")};return fmt.Sprint(n),nil});fmt.Println(out,err!=nil)','[1] true','Результат ошибочного callback не добавляется в накопленный срез.','func MapErr[E,R any](s []E,f func(E)(R,error))([]R,error){out:=make([]R,0,len(s));for _,v:=range s{r,e:=f(v);if e!=nil{return out,e};out=append(out,r)};return out,nil}');
q('Срез частичного результата удерживает ёмкость','out,_:=MapErr([]int{1,-1,3},func(n int)(int,error){if n<0{return 0,fmt.Errorf("stop")};return n,nil});fmt.Println(len(out),cap(out))','1 3','Длина успешного префикса и выделенная ёмкость — разные свойства договора API.','func MapErr[E,R any](s []E,f func(E)(R,error))([]R,error){out:=make([]R,0,len(s));for _,v:=range s{r,e:=f(v);if e!=nil{return out,e};out=append(out,r)};return out,nil}');
q('GroupBy выбирает тип ключа callback','groups:=Group([]string{"a","go","b"},func(s string)int{return len(s)});fmt.Printf("%T %v %v\\n",groups,groups[1],groups[2])','map[int][]string [a b] [go]','Тип ключа K выводится из результата функции группировки, порядок внутри групп сохраняет обход.','func Group[E any,K comparable](s []E,key func(E)K)map[K][]E{out:=map[K][]E{};for _,v:=range s{k:=key(v);out[k]=append(out[k],v)};return out}');
bad('GroupBy с ключом-срезом','_ = Group([]int{1},func(n int)[]int{return []int{n}})','does not satisfy comparable','Ключевой callback может вернуть срез, но такой K не подходит ограничению карты.','func Group[E any,K comparable](s []E,key func(E)K)map[K][]E{return nil}','');
q('GroupBy с any-ключом переносит отказ в runtime','defer func(){fmt.Println(recover()!=nil)}();_ = Group([]int{1},func(n int)any{return []int{n}})','true','K=any удовлетворяет ограничению, но конкретный динамический ключ не хешируем.','func Group[E any,K comparable](s []E,key func(E)K)map[K][]E{out:=map[K][]E{};for _,v:=range s{k:=key(v);out[k]=append(out[k],v)};return out}');
q('Индексирование дубликатов сохраняет последнего','m:=Index([]User{{1,"a"},{1,"b"}},func(u User)int{return u.ID});fmt.Println(len(m),m[1].Name)','1 b','Параметры типов не задают политику дубликатов; её определяет запись out[key]=value.','type User struct{ID int;Name string};func Index[E any,K comparable](s []E,key func(E)K)map[K]E{out:=map[K]E{};for _,v:=range s{out[key(v)]=v};return out}');
q('Generic MinBy выбирает первый при равенстве','v:=MinBy([]User{{2,"a"},{2,"b"}},func(a,b User)bool{return a.N<b.N});fmt.Println(v.Name)','a','Строгий callback Less не обновляет выбранный результат при равных ключах.','type User struct{N int;Name string};func MinBy[E any](s []E,less func(E,E)bool)E{m:=s[0];for _,v:=range s[1:]{if less(v,m){m=v}};return m}');
q('Именованный callback допускается как параметр функции','var f Pred=func(n int)bool{return n>0};fmt.Println(Any([]int{-1,2},f))','true','Определённый функциональный тип присваивается подходящему неназванному типу callback.','type Pred func(int)bool;func Any[E any](s []E,p func(E)bool)bool{for _,v:=range s{if p(v){return true}};return false}');
q('Generic алгоритм сохраняет тип callback в результате','var f Pred=func(n int)bool{return n>0};g:=Keep(f);fmt.Printf("%T %v\\n",g,g(1))','main.Pred true','Параметр F с underlying-функцией сохраняет её определённый тип.','type Pred func(int)bool;func Keep[F ~func(E)bool,E any](f F)F{return f}');
q('Generic Zip останавливается на коротком входе','fmt.Println(Zip([]int{1,2},[]string{"a"}))','[{1 a}]','Наличие двух параметров типов не определяет длину результата; данный алгоритм берёт минимум длин.','type Pair[A,B any]struct{A A;B B};func Zip[A,B any](a []A,b []B)(out []Pair[A,B]){for i:=0;i<len(a)&&i<len(b);i++{out=append(out,Pair[A,B]{a[i],b[i]})};return}');
bad('Типизированные callbacks не складываются в один []func(any)any','_ = []func(any)any{func(n int)string{return fmt.Sprint(n)}}','cannot use','Обобщение контейнера callback требует адаптации каждой сигнатуры; упаковка результатов недостаточна.');
section('Generic-интерфейсы и стратегии поведения');
q('Интерфейс параметризован входом и выходом','var m Mapper[int,string]=MF[int,string](func(n int)string{return fmt.Sprint(n)});fmt.Println(m.Map(7))','7','Инстанциация generic-интерфейса задаёт конкретную сигнатуру метода адаптера.','type Mapper[A,B any]interface{Map(A)B};type MF[A,B any]func(A)B;func(f MF[A,B])Map(a A)B{return f(a)}');
bad('Две инстанциации интерфейса не ковариантны','var a Mapper[int,string];var b Mapper[int,any]=a;_ = b','does not implement','Map(int)string не становится Map(int)any при присваивании интерфейса.','type Mapper[A,B any]interface{Map(A)B}','');
q('Явная обёртка расширяет результат','a:=MF[int,string](func(n int)string{return fmt.Sprint(n)});var b Mapper[int,any]=Widen[int,string]{a};fmt.Printf("%T %v\\n",b.Map(3),b.Map(3))','string 3','Обёртка реализует новую сигнатуру, явно упаковывая результат B в any.','type Mapper[A,B any]interface{Map(A)B};type MF[A,B any]func(A)B;func(f MF[A,B])Map(a A)B{return f(a)};type Widen[A,B any]struct{Inner Mapper[A,B]};func(w Widen[A,B])Map(a A)any{return w.Inner.Map(a)}');
q('Стратегия сравнения как generic-интерфейс','s:=[]string{"aaa","b"};fmt.Println(Pick(s,LenOrder{}))','b','Алгоритм отделяет тип данных от реализации сравнения, не требуя оператор < у E.','type Order[E any]interface{Less(E,E)bool};type LenOrder struct{};func(LenOrder)Less(a,b string)bool{return len(a)<len(b)};func Pick[E any](s []E,o Order[E])E{v:=s[0];for _,x:=range s[1:]{if o.Less(x,v){v=x}};return v}');
q('Функция адаптируется в стратегию','o:=OF[string](func(a,b string)bool{return len(a)>len(b)});fmt.Println(o.Less("go","x"))','true','Generic-функциональный тип добавляет метод Less к конкретному callback.','type OF[E any]func(E,E)bool;func(f OF[E])Less(a,b E)bool{return f(a,b)}');
q('Нулевой тип стратегии готов к использованию','fmt.Println(Pick[int,Ascending](3,2))','2','Нулевое значение stateless-стратегии допустимо, поскольку метод не требует состояния.','type Ascending struct{};func(Ascending)Less(a,b int)bool{return a<b};func Pick[E any,O interface{Less(E,E)bool}](a,b E)E{var o O;if o.Less(b,a){return b};return a}');
q('Нулевой pointer-стратегии недостаточно','defer func(){fmt.Println(recover()!=nil)}();fmt.Println(Pick[int,*Order](3,2))','true','Ограничение методом не обещает, что нулевой указатель стратегии пригоден к вызову.','type Order struct{Reverse bool};func(o *Order)Less(a,b int)bool{if o.Reverse{return a>b};return a<b};func Pick[E any,O interface{Less(E,E)bool}](a,b E)E{var o O;if o.Less(b,a){return b};return a}');
q('Стратегию можно передать готовым значением','fmt.Println(Pick(3,2,&Order{true}))','3','Передача сконфигурированной стратегии избегает предположения о пригодности её нулевого значения.','type Order struct{Reverse bool};func(o *Order)Less(a,b int)bool{if o.Reverse{return a>b};return a<b};func Pick[E any,O interface{Less(E,E)bool}](a,b E,o O)E{if o.Less(b,a){return b};return a}');
q('Add со своим типом обобщается','fmt.Println(Sum([]N{1,2},N(10)))','13','Параметр E одновременно обозначает элемент, аккумулятор и аргумент/результат метода Add.','type N int;func(n N)Add(m N)N{return n+m};func Sum[E interface{Add(E)E}](s []E,a E)E{for _,v:=range s{a=a.Add(v)};return a}');
bad('Add с возвратом указателя нарушает связь','fmt.Println(Sum([]N{1},N(0)))','does not satisfy','Требуемый Add(N)N не совпадает с Add(N)*N.','type N int;func(n N)Add(m N)*N{r:=n+m;return &r};func Sum[E interface{Add(E)E}](s []E,a E)E{return a}');
q('Операция может жить в отдельном типе','fmt.Println(Fold([]int{2,3},10,Plus{}))','15','Отдельный интерфейс операции позволяет работать с int, не добавляя методы встроенному типу.','type Op[E any]interface{Apply(E,E)E};type Plus struct{};func(Plus)Apply(a,b int)int{return a+b};func Fold[E any](s []E,a E,o Op[E])E{for _,v:=range s{a=o.Apply(a,v)};return a}');
q('Аккумулятор pointer и интерфейсный callback','a:=&Acc{};var op Step[int]=a;op.Add(2);op.Add(3);fmt.Println(a.N)','5','Инстанцированный интерфейс сохраняет pointer-семантику реализации с состоянием.','type Step[E any]interface{Add(E)};type Acc struct{N int};func(a *Acc)Add(n int){a.N+=n}');
bad('Value не получает методы pointer в generic-контракте','var op Step[int]=Acc{};_ = op','does not implement','Параметры интерфейса не изменяют правила множеств методов конкретной реализации.','type Step[E any]interface{Add(E)};type Acc struct{N int};func(a *Acc)Add(n int){a.N+=n}','');
q('Generic interface сохраняет динамический адаптер','var m Mapper[int,string]=MF[int,string](func(n int)string{return fmt.Sprint(n)});_,ok:=m.(MF[int,string]);fmt.Println(ok)','true','Инстанцированный обычный интерфейс поддерживает assertion на точный тип функционального адаптера.','type Mapper[A,B any]interface{Map(A)B};type MF[A,B any]func(A)B;func(f MF[A,B])Map(a A)B{return f(a)}');
q('Интерфейс как type argument проверяется динамически','var c C=Counter(3);fmt.Println(read[C](c))','3','Generic-функция может быть инстанцирована интерфейсным типом; вызов метода следует его динамическому значению.','type C interface{Get()int};type Counter int;func(c Counter)Get()int{return int(c)};func read[T C](v T)int{return v.Get()}');
q('Generic wrapper декорирует метод интерфейса','s:=Logged[int]{Next:SinkFunc[int](func(n int){fmt.Println("sink",n)})};s.Put(7)','before\nsink 7\nafter','Типизированная обёртка сохраняет E на всей цепочке и задаёт порядок вызовов.','type Sink[E any]interface{Put(E)};type SinkFunc[E any]func(E);func(f SinkFunc[E])Put(e E){f(e)};type Logged[E any]struct{Next Sink[E]};func(l Logged[E])Put(e E){fmt.Println("before");l.Next.Put(e);fmt.Println("after")}');
q('Type parameter стратегии не выводится из одного результата','fmt.Println(New[int,Identity[int]]().Map(4))','4','Явная инстанциация конструктора задаёт тип стратегии, которую нельзя выбрать только из E.','type Identity[E any]struct{};func(Identity[E])Map(e E)E{return e};func New[E any,M interface{Map(E)E}]()M{var m M;return m}');
bad('Конструктор не ищет реализацию стратегии','_ = New[int]()','cannot infer','Компилятор не ищет подходящий конкретный тип среди всех реализаций интерфейса.','func New[E any,M interface{Map(E)E}]()M{var m M;return m}','');
q('Список интерфейсных стратегий','ops:=[]Op[int]{Plus{},Mul{}};a:=2;for _,o:=range ops{a=o.Apply(a,3)};fmt.Println(a)','15','Один инстанцированный интерфейс объединяет разные реализации одной конкретной сигнатуры.','type Op[E any]interface{Apply(E,E)E};type Plus struct{};func(Plus)Apply(a,b int)int{return a+b};type Mul struct{};func(Mul)Apply(a,b int)int{return a*b}');
bad('Срез адаптеров не срез интерфейсов стратегий','s:=[]Plus{{}};var ops []Op[int]=s;_ = ops','cannot use','Реализация интерфейса каждым элементом не даёт присваиваемости целого среза.','type Op[E any]interface{Apply(E,E)E};type Plus struct{};func(Plus)Apply(a,b int)int{return a+b}','');
section('Reflection: динамические вызовы и функциональные адаптеры');
q('Call возвращает набор reflect.Value','f:=reflect.ValueOf(func(n int)(string,bool){return fmt.Sprint(n),n>0});out:=f.Call([]reflect.Value{reflect.ValueOf(3)});fmt.Println(len(out),out[0].String(),out[1].Bool())','2 3 true','Каждому результату функции соответствует отдельный Value с собственным типом.','','fmt,reflect');
q('Call variadic по отдельным аргументам','f:=reflect.ValueOf(func(xs ...int)int{return len(xs)});out:=f.Call([]reflect.Value{reflect.ValueOf(1),reflect.ValueOf(2)});fmt.Println(out[0].Int())','2','Call упаковывает отдельные variadic-аргументы в срез для вызываемой функции.','','fmt,reflect');
q('CallSlice раскрывает последний срез','f:=reflect.ValueOf(func(xs ...int)int{return len(xs)});out:=f.CallSlice([]reflect.Value{reflect.ValueOf([]int{1,2})});fmt.Println(out[0].Int())','2','CallSlice соответствует форме вызова f(slice...), а не передаче среза единичным элементом.','','fmt,reflect');
q('Call не раскрывает переданный срез','defer func(){fmt.Println(recover()!=nil)}();f:=reflect.ValueOf(func(xs ...int){});f.Call([]reflect.Value{reflect.ValueOf([]int{1,2})})','true','Call ожидает элементы int, поэтому []int не подходит без CallSlice.','','fmt,reflect');
q('CallSlice требует variadic-функцию','defer func(){fmt.Println(recover()!=nil)}();f:=reflect.ValueOf(func([]int){});f.CallSlice([]reflect.Value{reflect.ValueOf([]int{1})})','true','Обычный срезовый параметр не делает функцию variadic.','','fmt,reflect');
q('Упаковка int в interface-параметр Call','f:=reflect.ValueOf(func(v any)string{return fmt.Sprintf("%T",v)});out:=f.Call([]reflect.Value{reflect.ValueOf(3)});fmt.Println(out[0].String())','int','Reflect.Call допускает обычную присваиваемость конкретного int в параметр any.','','fmt,reflect');
q('Invalid Value не является nil-аргументом','defer func(){fmt.Println(recover()!=nil)}();f:=reflect.ValueOf(func(any){});f.Call([]reflect.Value{reflect.ValueOf(nil)})','true','Для nil-интерфейсного аргумента нужен валидный Value соответствующего типа.','','fmt,reflect');
q('Zero интерфейса как аргумент Call','f:=reflect.ValueOf(func(v any)bool{return v==nil});out:=f.Call([]reflect.Value{reflect.Zero(reflect.TypeFor[any]())});fmt.Println(out[0].Bool())','true','reflect.Zero(any) задаёт типизированное нулевое интерфейсное значение.','','fmt,reflect');
q('MakeFunc выпускает конкретную функцию','typ:=reflect.TypeFor[func(int)string]();v:=reflect.MakeFunc(typ,func(in []reflect.Value)[]reflect.Value{return []reflect.Value{reflect.ValueOf(fmt.Sprint(in[0].Int()*2))}});f:=v.Interface().(func(int)string);fmt.Println(f(4))','8','MakeFunc адаптирует callback над Value к выбранной конкретной функциональной сигнатуре.','','fmt,reflect');
q('MakeFunc сохраняет определённый функциональный тип','v:=reflect.MakeFunc(reflect.TypeFor[F](),func(in []reflect.Value)[]reflect.Value{return []reflect.Value{in[0]}});fmt.Printf("%T %v\\n",v.Interface(),v.Interface().(F)(7))','main.F 7','Тип создаваемой функции берётся точно из аргумента Type, включая определённое имя.','type F func(int)int','fmt,reflect');
q('MakeFunc проверяет количество результатов поздно','defer func(){fmt.Println(recover()!=nil)}();v:=reflect.MakeFunc(reflect.TypeFor[func()int](),func([]reflect.Value)[]reflect.Value{return nil});fmt.Println("created");v.Call(nil)','created\ntrue','Создание адаптера не исполняет callback; несоответствие числа результатов выявляется при вызове.','','fmt,reflect');
q('MakeFunc не преобразует результат int32 в int64','defer func(){fmt.Println(recover()!=nil)}();v:=reflect.MakeFunc(reflect.TypeFor[func()int64](),func([]reflect.Value)[]reflect.Value{return []reflect.Value{reflect.ValueOf(int32(1))}});v.Call(nil)','true','Результаты callback должны присваиваться объявленным типам без неявных числовых конверсий.','','fmt,reflect');
q('MakeFunc принимает конкретный результат для any','v:=reflect.MakeFunc(reflect.TypeFor[func()any](),func([]reflect.Value)[]reflect.Value{return []reflect.Value{reflect.ValueOf(7)}});f:=v.Interface().(func()any);fmt.Printf("%T %v\\n",f(),f())','int 7','Присваиваемость конкретного значения интерфейсу допустима и для результатов MakeFunc.','','fmt,reflect');
q('MakeFunc variadic получает один срез','v:=reflect.MakeFunc(reflect.TypeFor[func(...int)int](),func(in []reflect.Value)[]reflect.Value{fmt.Println(len(in),in[0].Kind());return []reflect.Value{reflect.ValueOf(in[0].Len())}});fmt.Println(v.Interface().(func(...int)int)(1,2,3))','1 slice\n3','Callback MakeFunc получает variadic-хвост уже упакованным в последний срезовый аргумент.','','fmt,reflect');
q('Отражённый bound method не ждёт receiver','v:=reflect.ValueOf(N(3)).MethodByName("Add");fmt.Println(v.Type().NumIn(),v.Call([]reflect.Value{reflect.ValueOf(2)})[0].Int())','1 5','Value.MethodByName связывает метод с текущим получателем.','type N int;func(n N)Add(x int)int{return int(n)+x}','fmt,reflect');
q('Отражённый unbound method ждёт receiver','m,_:=reflect.TypeFor[N]().MethodByName("Add");out:=m.Func.Call([]reflect.Value{reflect.ValueOf(N(3)),reflect.ValueOf(2)});fmt.Println(m.Type.NumIn(),out[0].Int())','2 5','Type.MethodByName описывает метод с явным первым параметром-получателем.','type N int;func(n N)Add(x int)int{return int(n)+x}','fmt,reflect');
q('Поиск pointer-метода у значения не берёт адрес','n:=N(1);v:=reflect.ValueOf(&n).Elem();fmt.Println(v.CanAddr(),v.MethodByName("Inc").IsValid(),v.Addr().MethodByName("Inc").IsValid())','true false true','Reflection не применяет синтаксическое сокращение (&n).Inc при поиске метода у N.','type N int;func(n *N)Inc(){*n++}','fmt,reflect');
q('Reflect callback сохраняет окружение после MakeFunc','n:=1;v:=reflect.MakeFunc(reflect.TypeFor[func()int](),func([]reflect.Value)[]reflect.Value{return []reflect.Value{reflect.ValueOf(n)}});n=9;fmt.Println(v.Interface().(func()int)())','9','Динамически созданная функция вызывает исходное замыкание с его текущим захваченным состоянием.','','fmt,reflect');
q('Call на nil function Value','defer func(){fmt.Println(recover()!=nil)}();var f func();v:=reflect.ValueOf(f);fmt.Println(v.IsValid(),v.IsNil());v.Call(nil)','true true\ntrue','Value валиден и содержит тип функции, но вызывать её nil-значение нельзя.','','fmt,reflect');
bad('Reflection не инстанцирует generic-имя','_ = reflect.ValueOf(id)','cannot infer','Generic-функцию требуется инстанцировать до передачи как обычного значения в reflection.','func id[T any](v T)T{return v}','reflect');
section('Reflection: мосты между данными и типизированным API');
q('Динамический mapper сохраняет тип выходного среза','out:=mapValue(reflect.ValueOf([]int{1,2}),reflect.ValueOf(func(n int)string{return fmt.Sprint(n)}));fmt.Printf("%T %v\\n",out.Interface(),out.Interface())','[]string [1 2]','Тип выходного элемента берётся из сигнатуры callback, а не из входного контейнера.','func mapValue(s,f reflect.Value)reflect.Value{out:=reflect.MakeSlice(reflect.SliceOf(f.Type().Out(0)),s.Len(),s.Len());for i:=0;i<s.Len();i++{out.Index(i).Set(f.Call([]reflect.Value{s.Index(i)})[0])};return out}','fmt,reflect');
q('Reflect mapper не конвертирует элементы автоматически','defer func(){fmt.Println(recover()!=nil)}();s:=reflect.ValueOf([]int32{1});f:=reflect.ValueOf(func(int64)int{return 1});f.Call([]reflect.Value{s.Index(0)})','true','Динамический общий цикл всё равно обязан согласовать конкретные типы входа и callback.','','fmt,reflect');
q('Явный Convert адаптирует вход Call','s:=reflect.ValueOf([]int32{7});f:=reflect.ValueOf(func(n int64)int64{return n+1});v:=s.Index(0).Convert(f.Type().In(0));fmt.Println(f.Call([]reflect.Value{v})[0].Int())','8','Конверсия по типу параметра создаёт явный мост между числовыми представлениями.','','fmt,reflect');
q('AssignableTo важнее одинакового Kind','a,b:=reflect.TypeFor[N](),reflect.TypeFor[int]();fmt.Println(a.Kind()==b.Kind(),a.AssignableTo(b),a.ConvertibleTo(b))','true false true','Проверка только Kind в динамическом адаптере пропускает различие определённых типов.','type N int','fmt,reflect');
q('Адаптер any-среза с динамическим элементом','s:=reflect.ValueOf([]any{int32(7)});fmt.Println(s.Index(0).Kind(),s.Index(0).Elem().Kind())','interface int32','Чтобы исследовать конкретное значение интерфейсного элемента, нужен отдельный Elem.','','fmt,reflect');
q('Nil-интерфейсный элемент и Elem','s:=reflect.ValueOf([]any{nil});v:=s.Index(0);fmt.Println(v.IsNil(),v.Elem().IsValid())','true false','Разворачивание nil-интерфейса не создаёт типизированного нулевого значения.','','fmt,reflect');
q('Set адаптирует конкретное значение в any-поле','var box struct{V any};v:=reflect.ValueOf(&box).Elem().Field(0);v.Set(reflect.ValueOf(N(3)));fmt.Printf("%T %v\\n",box.V,box.V)','main.N 3','Set использует присваиваемость и сохраняет конкретный динамический тип в интерфейсном поле.','type N int','fmt,reflect');
q('Set из any-поля в int требует разворачивания','defer func(){fmt.Println(recover()!=nil)}();src:=struct{V any}{7};var n int;reflect.ValueOf(&n).Elem().Set(reflect.ValueOf(src).Field(0))','true','Статический тип Value поля — any; его динамический int не разворачивается автоматически при Set.','','fmt,reflect');
q('Elem открывает конкретный тип для Set','src:=struct{V any}{7};var n int;reflect.ValueOf(&n).Elem().Set(reflect.ValueOf(src).Field(0).Elem());fmt.Println(n)','7','Явное разворачивание интерфейса позволяет присвоить значение конкретного совпадающего типа.','','fmt,reflect');
q('Reflect.New даёт указатель для Decoder','v:=reflect.New(reflect.TypeFor[struct{N int}]());e:=json.Unmarshal([]byte(`{"N":7}`),v.Interface());fmt.Println(v.Elem().Field(0).Int(),e==nil)','7 true','New создаёт адресуемый объект и указатель, который можно передать обычному интерфейсному API декодирования.','','fmt,reflect,encoding/json');
q('Decoder без указателя отвергает адаптацию','v:=reflect.Zero(reflect.TypeFor[struct{N int}]());e:=json.Unmarshal([]byte(`{"N":7}`),v.Interface());fmt.Println(e!=nil)','true','Наличие правильного типа структуры не даёт декодеру права изменять переданную копию значения.','','fmt,reflect,encoding/json');
q('Reflect.Append возвращает новый заголовок','s:=[]int{1};v:=reflect.ValueOf(s);out:=reflect.Append(v,reflect.ValueOf(2));fmt.Println(len(s),out.Len())','1 2','Append возвращает новое значение среза; переменная исходного заголовка не обновляется.','','fmt,reflect');
q('Отражённое расширение нужно записать обратно','s:=[]int{1};v:=reflect.ValueOf(&s).Elem();v.Set(reflect.Append(v,reflect.ValueOf(2)));fmt.Println(s)','[1 2]','Set адресуемого заголовка фиксирует результат отражённого append.','','fmt,reflect');
q('Reflect.Copy строка в байты','b:=make([]byte,3);n:=reflect.Copy(reflect.ValueOf(b),reflect.ValueOf("яx"));fmt.Println(n,b)','3 [209 143 120]','Специальный мост string → []byte переносит байты и поддерживается reflect.Copy.','','fmt,reflect');
q('Reflect.Copy не преобразует тип элемента','defer func(){fmt.Println(recover()!=nil)}();a:=make([]int64,1);reflect.Copy(reflect.ValueOf(a),reflect.ValueOf([]int32{1}))','true','Copy требует совпадения типов элементов, а не просто возможности конверсии каждого числа.','','fmt,reflect');
q('Срез массивом через Reflect.Convert остаётся копией','s:=[]int{1,2};a:=reflect.ValueOf(s).Convert(reflect.TypeFor[[2]int]()).Interface().([2]int);s[0]=9;fmt.Println(a)','[1 2]','Отражённая конверсия в значение массива следует обычной семантике копирования.','','fmt,reflect');
q('Срез указателем через Reflect.Convert разделяет данные','s:=[]int{1,2};p:=reflect.ValueOf(s).Convert(reflect.TypeFor[*[2]int]()).Interface().(*[2]int);s[0]=9;fmt.Println(*p)','[9 2]','Указательная конверсия создаёт представление того же массива, даже при выполнении через reflection.','','fmt,reflect');
q('Отражённый map-адаптер: отсутствующий ключ','m:=reflect.ValueOf(map[string]int{});v:=m.MapIndex(reflect.ValueOf("x"));fmt.Println(v.IsValid())','false','Отсутствие ключа представляется invalid Value, а не reflect.Zero типа элемента.','','fmt,reflect');
q('Отражённый map-адаптер: nil-интерфейс присутствует','m:=reflect.ValueOf(map[string]any{"x":nil});v:=m.MapIndex(reflect.ValueOf("x"));fmt.Println(v.IsValid(),v.IsNil())','true true','Валидное nil-интерфейсное значение позволяет отличить присутствующий ключ от отсутствующего.','','fmt,reflect');
q('Generic TypeFor не зависит от значения any','var x any=N(3);fmt.Println(types(x))','interface main.N','TypeFor[T] показывает статический аргумент generic-функции, TypeOf(v) — динамический тип интерфейса.','type N int;func types[T any](v T)(reflect.Kind,reflect.Type){return reflect.TypeFor[T]().Kind(),reflect.TypeOf(v)}','fmt,reflect');
section('Интерфейсные декораторы: делегирование и дополнительные методы');
q('Read-декоратор можно обойти через WriterTo','calls:=0;src:=Trace{strings.NewReader("go"),&calls};var dst bytes.Buffer;_,e:=io.Copy(&dst,src);fmt.Println(dst.String(),calls,e==nil)','go 0 true','Встроенный Reader продвигает WriterTo; io.Copy выбирает его, обходя переопределённый Read.','type Trace struct{*strings.Reader;Calls *int};func(t Trace)Read(p []byte)(int,error){*t.Calls++;return t.Reader.Read(p)}','fmt,io,strings,bytes');
q('Статическое сужение до Reader не скрывает WriterTo','calls:=0;var src io.Reader=Trace{strings.NewReader("go"),&calls};var dst bytes.Buffer;io.Copy(&dst,src);fmt.Println(calls)','0','Assertion внутри io.Copy видит методы динамического типа, даже если внешняя переменная имеет тип io.Reader.','type Trace struct{*strings.Reader;Calls *int};func(t Trace)Read(p []byte)(int,error){*t.Calls++;return t.Reader.Read(p)}','fmt,io,strings,bytes');
q('Именованное поле ограничивает методы декоратора','calls:=0;src:=Trace{Inner:strings.NewReader("go"),Calls:&calls};var dst bytes.Buffer;io.Copy(&dst,src);fmt.Println(dst.String(),calls>0)','go true','Непродвинутое поле не добавляет WriterTo, поэтому копирование обращается к методу Read обёртки.','type Trace struct{Inner io.Reader;Calls *int};func(t Trace)Read(p []byte)(int,error){*t.Calls++;return t.Inner.Read(p)}','fmt,io,strings,bytes');
q('Reader-only обёртка скрывает Close','src:=io.NopCloser(strings.NewReader("go"));var r io.Reader=OnlyRead{src};_,ok:=r.(io.Closer);fmt.Println(ok)','false','Встраивание именно интерфейса Reader продвигает только его методы, а не все методы содержащегося объекта.','type OnlyRead struct{io.Reader}','fmt,io,strings');
q('Встраивание ReadCloser сохраняет Close','src:=io.NopCloser(strings.NewReader("go"));var r io.Reader=Wrapped{src};_,ok:=r.(io.Closer);fmt.Println(ok)','true','Статический тип embedded-поля определяет набор продвинутых методов обёртки.','type Wrapped struct{io.ReadCloser}','fmt,io,strings');
q('Метод через embedded interface сохраняет старое значение','w:=Wrapper{I:V(1)};f:=w.Get;w.I=V(2);fmt.Println(f(),w.Get())','1 2','Продвинутый method value связывается с текущим получателем вложенного интерфейса в момент создания.','type I interface{Get()int};type V int;func(v V)Get()int{return int(v)};type Wrapper struct{I}');
q('Явный метод pointer-декоратора читает новое поле','w:=Wrapper{I:V(1)};f:=w.Get;w.I=V(2);fmt.Println(f())','2','Сохранённый указатель на обёртку позволяет её методу заново прочитать поле I при вызове.','type I interface{Get()int};type V int;func(v V)Get()int{return int(v)};type Wrapper struct{I I};func(w *Wrapper)Get()int{return w.I.Get()}');
q('Декоратор ошибок сохраняет цепочку через %w','root:=fmt.Errorf("root");wrapped:=fmt.Errorf("adapter: %w",root);fmt.Println(errors.Is(wrapped,root),wrapped==root)','true false','Обёртка является другим error-значением, но Unwrap позволяет errors.Is найти исходную ошибку.','','fmt,errors');
q('Форматирование %v разрывает цепочку','root:=fmt.Errorf("root");wrapped:=fmt.Errorf("adapter: %v",root);fmt.Println(errors.Is(wrapped,root))','false','Совпадающий текст ошибки не заменяет связь Unwrap.','','fmt,errors');
q('errors.As находит конкретный pointer через обёртку','root:=&E{7};err:=fmt.Errorf("layer: %w",root);var found *E;fmt.Println(errors.As(err,&found),found==root)','true true','As присваивает найденное динамическое значение переменной через указатель на целевой тип.','type E struct{N int};func(e *E)Error()string{return fmt.Sprint(e.N)}','fmt,errors');
q('errors.As может искать интерфейс поведения','err:=fmt.Errorf("layer: %w",&E{});var found interface{Temporary()bool};ok:=errors.As(err,&found);fmt.Println(ok,found.Temporary())','true true','Целью As может быть интерфейс, который реализует один из элементов цепочки.','type E struct{};func(*E)Error()string{return "E"};func(*E)Temporary()bool{return true}','fmt,errors');
q('Typed nil найден через errors.As','var p *E;var err error=p;var found *E;ok:=errors.As(err,&found);fmt.Println(ok,found==nil,err==nil)','true true false','Успех поиска типа не гарантирует ненулевое значение найденного указателя.','type E struct{};func(*E)Error()string{return "E"}','fmt,errors');
q('Неправильная цель errors.As вызывает panic','defer func(){fmt.Println(recover()!=nil)}();err:=&E{};var found *E;errors.As(err,found)','true','Цель должна быть ненулевым указателем на переменную, а не её текущим nil-значением.','type E struct{};func(*E)Error()string{return "E"}','fmt,errors');
q('errors.Join сохраняет несколько причин','a,b:=fmt.Errorf("a"),fmt.Errorf("b");err:=errors.Join(a,b);fmt.Println(errors.Is(err,a),errors.Is(err,b),errors.Unwrap(err)==nil)','true true true','Is обходит дерево ошибок; Unwrap-функция поддерживает только одиночный Unwrap() error.','','fmt,errors');
q('Декоратор определяет семантическое совпадение error','root:=Code(7);fmt.Println(errors.Is(root,Code(7)),errors.Is(root,Code(8)))','true false','Сравнимый конкретный тип ошибок сопоставляется по значению, а не только по идентичности указателя.','type Code int;func(c Code)Error()string{return fmt.Sprint(int(c))}','fmt,errors');
q('Custom Is добавляет правило сопоставления','fmt.Println(errors.Is(E{},sentinel))','true','Метод Is(target error) bool позволяет типу ошибки определить дополнительное совпадение.','var sentinel=errors.New("target");type E struct{};func(E)Error()string{return "E"};func(E)Is(t error)bool{return t==sentinel}','fmt,errors');
q('Интерфейс-фабрика возвращает скрытый тип','x:=New();fmt.Printf("%T %v\\n",x,x.Get());_,ok:=x.(interface{Reset()});fmt.Println(ok)','*main.counter 7\ntrue','Возврат узкого интерфейса не удаляет дополнительные методы динамического типа.','type counter struct{N int};func(c *counter)Get()int{return c.N};func(c *counter)Reset(){c.N=0};func New()interface{Get()int}{return &counter{7}}');
q('Обёртка-фасад действительно скрывает Reset','x:=Facade{&counter{7}};var i interface{Get()int}=x;_,ok:=i.(interface{Reset()});fmt.Println(i.Get(),ok)','7 false','Отдельный тип с именованным полем предоставляет только явно реализованные методы.','type counter struct{N int};func(c *counter)Get()int{return c.N};func(c *counter)Reset(){c.N=0};type Facade struct{Inner *counter};func(f Facade)Get()int{return f.Inner.Get()}');
q('Копия интерфейса не копирует внутреннюю карту','a:=Store{map[string]int{"x":1}};var i Getter=a;var j Getter=i;a.M["x"]=9;fmt.Println(i.Get("x"),j.Get("x"))','9 9','Оба интерфейса содержат копии структуры с общей картой; состояние таблицы остаётся разделяемым.','type Getter interface{Get(string)int};type Store struct{M map[string]int};func(s Store)Get(k string)int{return s.M[k]}');
bad('Декоратор меняет variadic-сигнатуру интерфейса','var i Logger=Wrap{};_ = i','does not implement','Метод Log([]any) не реализует Log(...any), несмотря на похожий способ хранения аргументов.','type Logger interface{Log(...any)};type Wrap struct{};func(Wrap)Log([]any){}','');
section('Сквозные задачи: ленивые цепочки, адаптеры и типы');
q('Generic MapSeq ленив до потребления','calls:=0;s:=MapSeq(slices.Values([]int{1,2}),func(n int)string{calls++;return fmt.Sprint(n)});fmt.Print(calls," ");fmt.Println(slices.Collect(s),calls)','0 [1 2] 2','Фабрика последовательности сохраняет callback, а преобразование выполняется при обходе.','func MapSeq[A,B any](src iter.Seq[A],f func(A)B)iter.Seq[B]{return func(yield func(B)bool){for v:=range src{if !yield(f(v)){return}}}}','fmt,iter,slices');
q('Ранний break ограничивает MapSeq','calls:=0;s:=MapSeq(slices.Values([]int{1,2,3}),func(n int)int{calls++;return n*2});for v:=range s{fmt.Println(v);break};fmt.Println(calls)','2\n1','Остановка потребителя передаётся через yield и предотвращает обработку оставшихся элементов.','func MapSeq[A,B any](src iter.Seq[A],f func(A)B)iter.Seq[B]{return func(yield func(B)bool){for v:=range src{if !yield(f(v)){return}}}}','fmt,iter,slices');
q('Повторный обход повторяет callback','calls:=0;s:=MapSeq(slices.Values([]int{1,2}),func(n int)int{calls++;return n});_ = slices.Collect(s);_ = slices.Collect(s);fmt.Println(calls)','4','Повторяемый источник не означает кеширование преобразованных результатов.','func MapSeq[A,B any](src iter.Seq[A],f func(A)B)iter.Seq[B]{return func(yield func(B)bool){for v:=range src{if !yield(f(v)){return}}}}','fmt,iter,slices');
q('Одноразовый источник меняет второй обход','s:=Once([]int{1,2});fmt.Println(slices.Collect(s),slices.Collect(s))','[1 2] []','Индекс, захваченный вне функции обхода, сохраняется между вызовами последовательности.','func Once[E any](s []E)iter.Seq[E]{i:=0;return func(yield func(E)bool){for i<len(s){v:=s[i];i++;if !yield(v){return}}}}','fmt,iter,slices');
q('Одноразовый источник продолжает после break','s:=Once([]int{1,2,3});for v:=range s{fmt.Println(v);break};fmt.Println(slices.Collect(s))','1\n[2 3]','Источник обновляет индекс перед yield, поэтому следующий обход начинается после уже выданного значения.','func Once[E any](s []E)iter.Seq[E]{i:=0;return func(yield func(E)bool){for i<len(s){v:=s[i];i++;if !yield(v){return}}}}','fmt,iter,slices');
q('Filter перед Map исключает лишние вызовы','calls:=0;s:=MapSeq(FilterSeq(slices.Values([]int{1,2,3}),func(n int)bool{return n%2==1}),func(n int)int{calls++;return n*10});fmt.Println(slices.Collect(s),calls)','[10 30] 2','Порядок ленивых стадий определяет, какие элементы достигают преобразования.','func FilterSeq[E any](s iter.Seq[E],p func(E)bool)iter.Seq[E]{return func(yield func(E)bool){for v:=range s{if p(v)&&!yield(v){return}}}};func MapSeq[A,B any](s iter.Seq[A],f func(A)B)iter.Seq[B]{return func(yield func(B)bool){for v:=range s{if !yield(f(v)){return}}}}','fmt,iter,slices');
q('Map перед Filter выполняется для всех','calls:=0;s:=FilterSeq(MapSeq(slices.Values([]int{1,2,3}),func(n int)int{calls++;return n*10}),func(n int)bool{return n>=20});fmt.Println(slices.Collect(s),calls)','[20 30] 3','Отфильтрованный результат уже прошёл предшествующую стадию Map и её эффекты.','func FilterSeq[E any](s iter.Seq[E],p func(E)bool)iter.Seq[E]{return func(yield func(E)bool){for v:=range s{if p(v)&&!yield(v){return}}}};func MapSeq[A,B any](s iter.Seq[A],f func(A)B)iter.Seq[B]{return func(yield func(B)bool){for v:=range s{if !yield(f(v)){return}}}}','fmt,iter,slices');
q('Ошибка как элемент Seq2 может быть пропущена','seq:=Parse(slices.Values([]string{"1","x","3"}));var out []int;for n,e:=range seq{if e!=nil{continue};out=append(out,n)};fmt.Println(out)','[1 3]','В этом протоколе источник продолжает после ошибки, а политику выбирает потребитель.','func Parse(s iter.Seq[string])iter.Seq2[int,error]{return func(yield func(int,error)bool){for v:=range s{n,e:=strconv.Atoi(v);if !yield(n,e){return}}}}','fmt,iter,slices,strconv');
q('Источник сам завершает Seq2 после ошибки','seq:=Parse(slices.Values([]string{"1","x","3"}));var out []int;for n,e:=range seq{if e!=nil{continue};out=append(out,n)};fmt.Println(out)','[1]','Одинаковая сигнатура Seq2 не гарантирует одинаковую политику завершения на ошибке.','func Parse(s iter.Seq[string])iter.Seq2[int,error]{return func(yield func(int,error)bool){for v:=range s{n,e:=strconv.Atoi(v);if !yield(n,e)||e!=nil{return}}}}','fmt,iter,slices,strconv');
q('iter.Pull требует stop при раннем выходе','closed:=false;seq:=func(yield func(int)bool){defer func(){closed=true}();if !yield(1){return};yield(2)};next,stop:=iter.Pull(seq);v,ok:=next();fmt.Println(v,ok,closed);stop();fmt.Println(closed)','1 true false\ntrue','Pull приостанавливает источник внутри yield; stop завершает обход и запускает defer источника.','','fmt,iter');
q('Повторный stop и next после остановки','seq:=func(yield func(int)bool){yield(1)};next,stop:=iter.Pull(seq);next();stop();stop();v,ok:=next();fmt.Println(v,ok)','0 false','После stop последовательность завершена; повторный stop допустим, next возвращает нулевое значение и false.','','fmt,iter');
q('Итератор из метода среза сохраняет старую длину','s:=Numbers{1};seq:=s.All();s=append(s,2);fmt.Println(slices.Collect(seq))','[1]','Метод с value receiver сохраняет заголовок среза на момент создания итератора.','type Numbers []int;func(s Numbers)All()iter.Seq[int]{return func(yield func(int)bool){for _,v:=range s{if !yield(v){return}}}}','fmt,iter,slices');
q('Итератор через pointer receiver видит новый срез','s:=Numbers{1};seq:=s.All();s=append(s,2);fmt.Println(slices.Collect(seq))','[1 2]','Замыкание хранит указатель на переменную среза и читает её при начале обхода.','type Numbers []int;func(s *Numbers)All()iter.Seq[int]{return func(yield func(int)bool){for _,v:=range *s{if !yield(v){return}}}}','fmt,iter,slices');
q('Интерфейс источника сохраняет параметр элемента','var src Source[int]=Values[int]{1,2};fmt.Println(slices.Collect(src.All()))','[1 2]','Generic-интерфейс описывает фабрику типизированной последовательности без раскрытия контейнера.','type Source[E any]interface{All()iter.Seq[E]};type Values[E any][]E;func(v Values[E])All()iter.Seq[E]{return slices.Values(v)}','fmt,iter,slices');
bad('Source[int] не становится Source[any]','var src Source[int];var dst Source[any]=src;_ = dst','does not implement','Типы результата iter.Seq[int] и iter.Seq[any] различаются; ковариантности фабрик нет.','type Source[E any]interface{All()iter.Seq[E]}','iter');
q('Явная стадия упаковывает поток в any','s:=MapSeq(slices.Values([]int{1,2}),func(n int)any{return n});out:=slices.Collect(s);fmt.Printf("%T %T\\n",out,out[0])','[]interface {} int','Callback задаёт переход int → any, а тип контейнера результата становится []any.','func MapSeq[A,B any](s iter.Seq[A],f func(A)B)iter.Seq[B]{return func(yield func(B)bool){for v:=range s{if !yield(f(v)){return}}}}','fmt,iter,slices');
q('Reflection внутри generic callback меняет именованный int','out:=Map([]N{2,3},func(n N)int{return int(reflect.ValueOf(n).Int())});fmt.Printf("%T %v\\n",out,out)','[]int [2 3]','Отражённое чтение и явная конверсия отделяют представление N от нового результата int.','type N int;func Map[A,B any](s []A,f func(A)B)(out []B){for _,v:=range s{out=append(out,f(v))};return}','fmt,reflect');
q('MakeFunc-адаптер работает в generic Map','v:=reflect.MakeFunc(reflect.TypeFor[func(int)string](),func(in []reflect.Value)[]reflect.Value{return []reflect.Value{reflect.ValueOf(fmt.Sprint(in[0].Int()))}});out:=Map([]int{1,2},v.Interface().(func(int)string));fmt.Println(out)','[1 2]','После assertion динамически созданная функция имеет обычную конкретную сигнатуру для вывода generic-параметров.','func Map[A,B any](s []A,f func(A)B)(out []B){for _,v:=range s{out=append(out,f(v))};return}','fmt,reflect');
q('Адаптер iterator callback возвращает error через захват','var failure error;s:=MapSeq(slices.Values([]int{1,-1,3}),func(n int)int{if n<0{failure=fmt.Errorf("bad")};return n});var out []int;for n:=range s{if failure!=nil{break};out=append(out,n)};fmt.Println(out,failure!=nil)','[1] true','Побочный канал ошибки требует согласованного порядка чтения; тип iter.Seq[int] сам о нём ничего не сообщает.','func MapSeq[A,B any](s iter.Seq[A],f func(A)B)iter.Seq[B]{return func(yield func(B)bool){for v:=range s{if !yield(f(v)){return}}}}','fmt,iter,slices');
q('Чистая композиция с разными тремя типами','toText:=func(n int)string{return fmt.Sprint(n)};toLen:=func(s string)int{return len(s)};toBool:=func(n int)bool{return n>1};f:=Compose(toBool,Compose(toLen,toText));fmt.Printf("%T %v %v\\n",f,f(7),f(42))','func(int) bool false true','Промежуточные параметры связывают int → string → int → bool без интерфейсной упаковки и reflection.','func Compose[A,B,C any](f func(B)C,g func(A)B)func(A)C{return func(a A)C{return f(g(a))}}');
